    26  GenericHash::GenericHash(NetworkInterface *_iface, u_int _num_hashes,
    27                           u_int _max_hash_size, const char *_name) {
    28    num_hashes = _num_hashes;
    29    current_size = 0;
    30    /* Allow the total number of entries (that is, active and those idle but still
    31       not yet purged) to be 30% more than the maximum hash table size specified.
    32       This prevents memory from growing indefinitely when for example the purging
    33       is slow. */
    34    max_hash_size = _max_hash_size * 1.3;
    35    upper_num_visited_entries = min_val(200000, (max_hash_size / 10));
    36    last_entry_id = 0;
    37    purge_step = max_val(num_hashes / PURGE_FRACTION, 1);
    38    walk_idle_start_hash_id = 0;
    39    name = strdup(_name ? _name : "???");
    40    memset(&entry_state_transition_counters, 0,
    41           sizeof(entry_state_transition_counters));
    42
    43    iface = _iface;
    44    idle_entries = idle_entries_shadow = NULL;
    45
    46    table = new (std::nothrow) GenericHashEntry *[num_hashes];
    47    for (u_int i = 0; i < num_hashes; i++) table[i] = NULL;
    48
    49    locks = new (std::nothrow) RwLock *[num_hashes];
    50    for (u_int i = 0; i < num_hashes; i++) locks[i] = new (std::nothrow) RwLock();
    51
    52    idle_entries_in_use = new (std::nothrow) vector<GenericHashEntry *>;
    53
    54    last_purged_hash = _num_hashes - 1;
    55
    56    hash_mask = (u_int32_t)iface->get_id();
    57
    58    /* We take the least significat 8 bit */
    59    hash_mask &= 0x000000FF;
    60
    61    /* We shift it of 24 bit */
    62    hash_mask = hash_mask << 24;
    63  }
